SELECT 
FROM chatbi.bid_biz_bidding

    AND province = #{province}
    AND city = #{city}
    AND industry = #{industry}
    AND info_type = #{infoType}
    AND tenderer LIKE CONCAT('%', #{tenderer}, '%')

        AND (
          title LIKE CONCAT('%', #{keyword}, '%')
          OR project_name LIKE CONCAT('%', #{keyword}, '%')
          OR product LIKE CONCAT('%', #{keyword}, '%')
          OR keywords LIKE CONCAT('%', #{keyword}, '%')
        )

    AND bidding_budget >= #{minBudgetYuan}
    AND bidding_budget <= #{maxBudgetYuan}
    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT tenderer AS company_name, COUNT(*) AS purchase_count, COALESCE(SUM(bidding_budget), 0) AS total_amount, MAX(publish_time) AS latest_purchase_time FROM chatbi.bid_biz_bidding
tenderer IS NOT NULL AND tenderer != ''
title LIKE CONCAT('%', #{kw}, '%') OR project_name LIKE CONCAT('%', #{kw}, '%') OR product LIKE CONCAT('%', #{kw}, '%') OR keywords LIKE CONCAT('%', #{kw}, '%') OR tenderer LIKE CONCAT('%', #{kw}, '%')
AND province IN
#{p}
AND bidding_budget >= #{minBudget} AND bidding_budget <= #{maxBudget} AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
GROUP BY tenderer ORDER BY purchase_count DESC, total_amount DESC LIMIT #{limit}

SELECT tenderer AS fullname, tenderer AS name, COUNT(*) AS bid_count, MAX(province) AS province, MAX(city) AS city, MAX(publish_time) AS latest_pub_time FROM chatbi.bid_biz_bidding
tenderer IS NOT NULL AND tenderer != '' AND tenderer LIKE CONCAT('%', #{companyName}, '%') AND province = #{province} AND city = #{city}
GROUP BY tenderer ORDER BY bid_count DESC LIMIT #{limit}

SELECT w.win_tenderer AS company_name, COUNT(*) AS cooperation_count, COALESCE(SUM(w.win_bid_price), 0) AS cooperation_amount, MAX(w.publish_time) AS last_cooperation_time, GROUP_CONCAT(DISTINCT b.product SEPARATOR ',') AS products FROM chatbi.bid_biz_bidding b INNER JOIN chatbi.bid_biz_win_bid w ON b.project_name = w.project_name
b.tenderer = #{companyName} AND w.win_tenderer IS NOT NULL AND w.win_tenderer != ''
AND b.province IN
#{p}
b.title LIKE CONCAT('%', #{kw}, '%') OR b.product LIKE CONCAT('%', #{kw}, '%') OR b.keywords LIKE CONCAT('%', #{kw}, '%') OR b.project_name LIKE CONCAT('%', #{kw}, '%')
AND w.win_bid_price >= #{minAmount} AND w.publish_time >= #{beginDate} AND w.publish_time <= #{endDate}
GROUP BY w.win_tenderer ORDER BY cooperation_count DESC, cooperation_amount DESC LIMIT #{limit}

SELECT
    product AS keyword,
    COUNT(*) AS count,
    COALESCE(SUM(bidding_budget), 0) AS amount
FROM chatbi.bid_biz_bidding

    tenderer = #{companyName}
    AND product IS NOT NULL AND product != ''

        AND province IN

            #{p}


    AND publish_time >= #{beginDate}
    AND publish_time <= #{endDate}

GROUP BY product
ORDER BY count DESC, amount DESC
LIMIT #{limit}

SELECT w.win_tenderer AS company_name, COUNT(*) AS caller_history_count, COALESCE(SUM(w.win_bid_price), 0) AS caller_history_amount, MAX(w.publish_time) AS last_win_time, GROUP_CONCAT(DISTINCT b.product SEPARATOR ',') AS matched_products FROM chatbi.bid_biz_bidding b INNER JOIN chatbi.bid_biz_win_bid w ON b.project_name = w.project_name
b.tenderer = #{companyName} AND w.win_tenderer IS NOT NULL AND w.win_tenderer != ''
AND (b.product LIKE CONCAT('%', #{product}, '%') OR b.keywords LIKE CONCAT('%', #{product}, '%') OR b.title LIKE CONCAT('%', #{product}, '%'))
AND b.province = #{province}
GROUP BY w.win_tenderer ORDER BY caller_history_count DESC, caller_history_amount DESC LIMIT #{limit}

SELECT
province AS bucket_key, industry AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m') AS bucket_key, DATE_FORMAT(publish_time, '%Y-%m-%d') AS bucket_key, province AS bucket_key,
COUNT(*) AS cnt, COALESCE(SUM(bidding_budget), 0) AS sum_amount FROM chatbi.bid_biz_bidding
title LIKE CONCAT('%', #{kw}, '%') OR project_name LIKE CONCAT('%', #{kw}, '%') OR product LIKE CONCAT('%', #{kw}, '%') OR keywords LIKE CONCAT('%', #{kw}, '%')
AND province IN
#{p}
AND bidding_budget >= #{minBudget} AND bidding_budget <= #{maxBudget} AND publish_time >= #{beginDate} AND publish_time <= #{endDate}
GROUP BY bucket_key ORDER BY cnt DESC LIMIT #{limit}
